#!/usr/bin/env node
/**
 * Task-local packager for the slack-api skill.
 * Validates the skill folder against the official skill-creator rules, then
 * packages it into slack-api.skill (a zip archive whose entries mirror the
 * official packager layout: contents of the skill folder at the archive root).
 * Zero external dependencies (uses zlib deflate + a CRC32 table).
 *
 * Usage: node package_slack_api.cjs [skill-dir] [output-file]
 */

'use strict';

const fs = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');

const DEFAULT_SKILL_DIR = 'slack-api';
const DEFAULT_OUTPUT = 'slack-api.skill';

// --- validation (mirrors .codex/skills/skill-creator/scripts/validate_skill.cjs) ---

function walkFiles(dir, list = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (!['node_modules', '.git', '__pycache__'].includes(entry.name)) walkFiles(full, list);
    } else {
      list.push(full);
    }
  }
  return list;
}

function validate(skillDir) {
  const errors = [];
  if (!fs.existsSync(skillDir) || !fs.statSync(skillDir).isDirectory()) {
    return [`skill directory not found: ${skillDir}`];
  }
  const mdPath = path.join(skillDir, 'SKILL.md');
  if (!fs.existsSync(mdPath)) return ['SKILL.md not found'];
  const content = fs.readFileSync(mdPath, 'utf8');
  if (!content.startsWith('---')) errors.push('SKILL.md has no YAML frontmatter');
  const parts = content.split('---');
  if (parts.length < 3) errors.push('invalid frontmatter format');
  const frontmatter = parts[1];
  const nameMatch = frontmatter.match(/^name:\s*(.+)$/m);
  const descMatch = frontmatter.match(/^description:\s*(?:'([^']*)'|"([^"]*)"|(.+))$/m);
  if (!nameMatch) errors.push('missing "name" in frontmatter');
  if (!descMatch) errors.push('description must be a single-line string');
  const name = nameMatch ? nameMatch[1].trim() : '';
  const description = descMatch
    ? (descMatch[1] !== undefined ? descMatch[1] : descMatch[2] !== undefined ? descMatch[2] : descMatch[3] || '').trim()
    : '';
  if (name !== path.basename(skillDir)) errors.push(`frontmatter name "${name}" must match folder name "${path.basename(skillDir)}"`);
  if (name && !/^[a-z0-9-]+$/.test(name)) errors.push(`name "${name}" should be hyphen-case (lowercase letters, digits, hyphens)`);
  if (description.length > 1024) errors.push('description too long (max 1024 chars)');
  if (description.includes('\n')) errors.push('description must not contain newlines');
  for (const file of walkFiles(skillDir)) {
    const text = fs.readFileSync(file, 'utf8');
    if (text.includes('TODO:')) {
      errors.push(`unresolved TODO: in ${path.relative(skillDir, file)}`);
    }
  }
  const mdRelLinks = [...content.matchAll(/\]\(([^)#]+)\)/g)].map((m) => m[1]);
  for (const rel of mdRelLinks) {
    if (rel.startsWith('http')) continue;
    const target = path.join(skillDir, rel);
    if (!fs.existsSync(target)) errors.push(`SKILL.md references missing file: ${rel}`);
  }
  return errors;
}

// --- minimal ZIP writer (stored/deflated, UTF-8 names) ---

const CRC_TABLE = (() => {
  const table = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    table[n] = c >>> 0;
  }
  return table;
})();

function crc32(buf) {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function dosDateTime(date) {
  const time = (date.getHours() << 11) | (date.getMinutes() << 5) | Math.floor(date.getSeconds() / 2);
  const day = ((date.getFullYear() - 1980) << 9) | ((date.getMonth() + 1) << 5) | date.getDate();
  return { time: time & 0xffff, day: day & 0xffff };
}

function buildZip(entries) {
  const localParts = [];
  const centralParts = [];
  let offset = 0;

  for (const { name, data, mtime } of entries) {
    const nameBuf = Buffer.from(name, 'utf8');
    const crc = crc32(data);
    let method = 8;
    let compressed = zlib.deflateRawSync(data, { level: 9 });
    if (compressed.length >= data.length) {
      method = 0;
      compressed = data;
    }
    const { time, day } = dosDateTime(mtime);
    const local = Buffer.alloc(30 + nameBuf.length);
    local.writeUInt32LE(0x04034b50, 0);
    local.writeUInt16LE(20, 4);
    local.writeUInt16LE(0x0800, 6); // UTF-8 name flag
    local.writeUInt16LE(method, 8);
    local.writeUInt16LE(time, 10);
    local.writeUInt16LE(day, 12);
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(compressed.length, 18);
    local.writeUInt32LE(data.length, 22);
    local.writeUInt16LE(nameBuf.length, 26);
    local.writeUInt16LE(0, 28);
    nameBuf.copy(local, 30);
    localParts.push(local, compressed);
    const localLen = local.length + compressed.length;

    const central = Buffer.alloc(46 + nameBuf.length);
    central.writeUInt32LE(0x02014b50, 0);
    central.writeUInt16LE(20, 4); // version made by
    central.writeUInt16LE(20, 6); // version needed
    central.writeUInt16LE(0x0800, 8);
    central.writeUInt16LE(method, 10);
    central.writeUInt16LE(time, 12);
    central.writeUInt16LE(day, 14);
    central.writeUInt32LE(crc, 16);
    central.writeUInt32LE(compressed.length, 20);
    central.writeUInt32LE(data.length, 24);
    central.writeUInt16LE(nameBuf.length, 28);
    central.writeUInt16LE(0, 30); // extra len
    central.writeUInt16LE(0, 32); // comment len
    central.writeUInt16LE(0, 34); // disk start
    central.writeUInt16LE(0, 36); // internal attrs
    central.writeUInt32LE(0, 38); // external attrs
    central.writeUInt32LE(offset, 42); // local header offset
    nameBuf.copy(central, 46);
    centralParts.push(central);
    offset += localLen;
  }

  const centralDir = Buffer.concat(centralParts);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);
  eocd.writeUInt16LE(0, 4);
  eocd.writeUInt16LE(0, 6);
  eocd.writeUInt16LE(entries.length, 8);
  eocd.writeUInt16LE(entries.length, 10);
  eocd.writeUInt32LE(centralDir.length, 12);
  eocd.writeUInt32LE(offset, 16);
  eocd.writeUInt16LE(0, 20);
  return Buffer.concat([...localParts, centralDir, eocd]);
}

// --- main ---

function main() {
  const args = process.argv.slice(2);
  const skillDir = path.resolve(args[0] || DEFAULT_SKILL_DIR);
  const outputFile = path.resolve(args[1] || DEFAULT_OUTPUT);

  console.log('Validating skill...');
  const errors = validate(skillDir);
  if (errors.length > 0) {
    for (const error of errors) console.error(`- ${error}`);
    console.error('Validation FAILED - not packaging.');
    process.exit(1);
  }
  console.log('Validation OK (frontmatter, name, description, links, no TODOs).');

  const files = walkFiles(skillDir).sort();
  const entries = files.map((file) => {
    const rel = path.relative(skillDir, file).split(path.sep).join('/');
    const stat = fs.statSync(file);
    return { name: rel, data: fs.readFileSync(file), mtime: stat.mtime };
  });

  const archive = buildZip(entries);
  fs.writeFileSync(outputFile, archive);
  console.log(`Packaged ${entries.length} file(s) into ${outputFile} (${archive.length} bytes):`);
  for (const entry of entries) {
    console.log(`  - ${entry.name} (${entry.data.length} bytes)`);
  }
  console.log('Done.');
}

main();

