#!/usr/bin/env node
/**
 * Slack Web API helper.
 *
 * Usage (run from the skill directory or with a full path):
 *   SLACK_TOKEN=xoxb-... node slack_api.cjs <method> '{"key":"value",...}' [flags]
 *   SLACK_TOKEN=xoxb-... node slack_api.cjs <method> key=value key2=value2 [flags]
 *
 * Flags:
 *   --paginate <field>   Follow response_metadata.next_cursor until empty, collecting the <field> array
 *   --limit <n>          Page size for paginated calls (default 200)
 *   --max-pages <n>      Safety cap on pages (default 200)
 *   --raw                Do not truncate printed JSON (default truncates at ~4000 chars)
 *
 * Exit codes: 0 success, 1 Slack/network error, 2 usage error.
 * Prints clean one-line results/errors on purpose (agentic ergonomics): no stack traces.
 */

'use strict';

const BASE_URL = 'https://slack.com/api/';
const REQUEST_TIMEOUT_MS = 30000;
const MAX_PAGES_DEFAULT = 200;
const PREVIEW_LIMIT = 4000;

// These params carry Unix-second timestamps; keep decimal values as strings
// so precision survives JSON transport (converting to a JS number can corrupt ts).
const TIMESTAMP_KEYS = new Set(['ts', 'thread_ts', 'oldest', 'latest']);

function usageText() {
  return [
    'Usage:',
    '  SLACK_TOKEN=xoxb-... node slack_api.cjs <method> \'{"key":"value",...}\' [flags]',
    '  SLACK_TOKEN=xoxb-... node slack_api.cjs <method> key=value key2=value2 [flags]',
    '',
    'Flags:',
    '  --paginate <field>   Follow next_cursor until the end, collecting the <field> array',
    '  --limit <n>          Page size for paginated calls (default 200)',
    '  --max-pages <n>      Safety cap on pages (default 200)',
    '  --raw                Do not truncate the printed JSON',
  ].join('\n');
}

function parseScalar(token) {
  // Parse JSON scalars/objects when valid; otherwise keep the raw string.
  try {
    return JSON.parse(token.trim());
  } catch {
    return token.trim();
  }
}

function buildParams(tokens) {
  const params = {};
  for (const token of tokens) {
    if (token.startsWith('{') || token.startsWith('[')) {
      let doc;
      try {
        doc = JSON.parse(token);
      } catch {
        throw new Error(`invalid JSON argument: ${token.slice(0, 80)}`);
      }
      if (typeof doc !== 'object' || doc === null || Array.isArray(doc)) {
        throw new Error('JSON argument must be an object of method params');
      }
      Object.assign(params, doc);
      continue;
    }
    const eq = token.indexOf('=');
    if (eq <= 0) {
      throw new Error(`cannot parse argument "${token}" (expected key=value or a JSON object)`);
    }
    const key = token.slice(0, eq).trim();
    const rawValue = token.slice(eq + 1);
    const value = parseScalar(rawValue);
    if (TIMESTAMP_KEYS.has(key) && typeof value === 'number' && !Number.isInteger(value)) {
      params[key] = rawValue; // keep decimal timestamps as strings
    } else {
      params[key] = value;
    }
  }
  return params;
}

async function request(method, params) {
  const token = process.env.SLACK_TOKEN;
  if (!token) {
    console.error(
      'Error: SLACK_TOKEN is not set. Obtain a Slack token and export it, e.g. `export SLACK_TOKEN=xoxb-...`',
    );
    return null;
  }
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
  try {
    const response = await fetch(BASE_URL + method, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json; charset=utf-8',
      },
      body: JSON.stringify(params),
      signal: controller.signal,
    });
    let data = null;
    try {
      data = await response.json();
    } catch {
      /* non-JSON body */
    }
    if (!response.ok) {
      const extra = data && data.error ? ` (error: ${data.error})` : '';
      console.error(`Error: Slack returned HTTP ${response.status}${extra}`);
      return null;
    }
    if (!data || data.ok === false) {
      if (data && data.error) {
        let msg = `Slack API error: ${data.error}`;
        if (data.needed) msg += ` — missing scope "${data.needed}"`;
        if (data.retry_after != null) msg += ` — retry after ${data.retry_after}s`;
        console.error(msg);
      } else {
        console.error('Slack API error: malformed response (missing "ok" field)');
      }
      return null;
    }
    return data;
  } catch (err) {
    if (err && err.name === 'AbortError') {
      console.error(`Error: request timed out after ${REQUEST_TIMEOUT_MS / 1000}s`);
    } else {
      console.error(`Error: request failed: ${err && err.message ? err.message : String(err)}`);
    }
    return null;
  } finally {
    clearTimeout(timer);
  }
}

function printResult(label, value, raw) {
  const text = JSON.stringify(value, null, 2);
  if (raw || text.length <= PREVIEW_LIMIT) {
    console.log(`${label}:`);
    console.log(text);
    return;
  }
  console.log(`${label} (truncated to ${PREVIEW_LIMIT} chars; rerun with --raw for the full JSON):`);
  console.log(text.slice(0, PREVIEW_LIMIT));
}

async function runSingle(method, params, raw) {
  const data = await request(method, params);
  if (!data) return 1;
  printResult('Success', data, raw);
  return 0;
}

async function runPaginated(method, params, field, limit, maxPages, raw) {
  const items = [];
  let cursor = '';
  let pages = 0;
  const body = { ...params };
  body.limit = limit || 200;
  for (;;) {
    if (cursor) body.cursor = cursor;
    const data = await request(method, body);
    if (!data) return 1;
    const batch = data[field];
    if (!Array.isArray(batch)) {
      console.error(
        `Error: response has no array field "${field}" (top-level fields: ${Object.keys(data).join(', ')})`,
      );
      return 1;
    }
    items.push(...batch);
    cursor = (data.response_metadata && data.response_metadata.next_cursor) || '';
    pages += 1;
    if (!cursor) break;
    if (pages >= maxPages) {
      console.error(
        `Error: stopped after ${pages} pages (--max-pages ${maxPages}); response still has next_cursor`,
      );
      return 1;
    }
  }
  const out = { ok: true, method, count: items.length, [field]: items };
  printResult(`Success: collected ${items.length} item(s) across ${pages} page(s)`, out, raw);
  return 0;
}

async function main(argv) {
  const args = argv.slice(2);
  const method = args.shift();
  if (!method || method.startsWith('-')) {
    console.error(usageText());
    return 2;
  }
  let paginateField = null;
  let limit = null;
  let maxPages = MAX_PAGES_DEFAULT;
  let raw = false;
  const tokens = [];
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--paginate') {
      paginateField = args[++i];
      if (!paginateField || paginateField.startsWith('-')) {
        console.error('Error: --paginate requires an array field name (e.g. --paginate channels)');
        return 2;
      }
    } else if (arg === '--limit') {
      limit = Number(args[++i]);
      if (!Number.isInteger(limit) || limit < 1) {
        console.error('Error: --limit requires a positive integer');
        return 2;
      }
    } else if (arg === '--max-pages') {
      maxPages = Number(args[++i]);
      if (!Number.isInteger(maxPages) || maxPages < 1) {
        console.error('Error: --max-pages requires a positive integer');
        return 2;
      }
    } else if (arg === '--raw') {
      raw = true;
    } else {
      tokens.push(arg);
    }
  }
  let params;
  try {
    params = buildParams(tokens);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    console.error(usageText());
    return 2;
  }
  if (paginateField) {
    return runPaginated(method, params, paginateField, limit, maxPages, raw);
  }
  return runSingle(method, params, raw);
}

if (require.main === module) {
  if (typeof fetch !== 'function') {
    console.error('Error: this helper requires Node.js 18+ (global fetch is unavailable).');
    process.exit(1);
  }
  main(process.argv).then(
    (code) => {
      process.exitCode = code;
    },
    (err) => {
      console.error(`Error: ${err && err.message ? err.message : String(err)}`);
      process.exitCode = 1;
    },
  );
}

module.exports = { request, main };
